// 真Common头与原Family纯控制reader的窄边界；typed控制链夹具不冒完整Family授权/Task钱货运行。
#include "resident/domains/tasks/personal_reports/task_personal_report_control.hpp"
#include "resident/domains/tasks/personal_reports/task_personal_report_state.hpp"
#include "resident/domains/tasks/personal_messages/task_personal_message_control.hpp"
#include "resident/domains/family/family_model.hpp"
#include "resident/domains/family/family_legacy.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void need(bool v,const char* why){++checks;if(!v)throw std::runtime_error(why);}
struct Fixture {
 std::shared_ptr<CommonCatalog> catalog=std::make_shared<CommonCatalog>();CommonStore common{CommonState{},catalog};FamilyState family;FamilyLegacyState legacy;
 Fixture(){common.state().identity.tick=4;common.state().identity.execution_epoch=1;common.state().metadata.player_actor_id="old";family.founder_actor_id="old";for(const auto* id:{"old","new"}){ActorRecord a;a.id=id;a.alive=true;a.available=true;common.state().actors.insert(id,a);}}
 StableId fact(const StableId& prefix,const StableId& kind,const StableId& domain){auto id=common.next_id(prefix);need(id.ok&&common.append_fact({id.value,kind,domain}).ok,"actual ordered Common fact");return id.value;}
 StableId report(const StableId& kind=task_personal_report_started_kind){return fact(kind,kind,task_personal_report_module);}
 StableId switch_old(){auto id=fact("family","family_succession","family");FamilyChoice change;change.kind="family_succession";change.guardian_actor_id="old";change.heir_actor_id="new";change.tick=4;family.facts.insert(id,change);family.successions.push_back(id);need(common.set_player_actor("new").ok,"original Common control write");return id;}
 StableId switch_legacy(){auto consent=fact("legacy","family_legacy_control_consent","family_legacy");FamilyLegacyConsentFact s;s.source.predecessor_actor_id="old";s.source.successor_actor_id="new";legacy.consents.insert(consent,s);auto id=fact("legacy","family_legacy_control_activated","family_legacy");FamilyLegacyActivationFact a;a.consent_fact_id=consent;a.tick=4;legacy.activations.insert(id,a);need(common.set_player_actor("new").ok,"original Common legacy control write");return id;}
};}
int main(){try{
 Fixture f;const auto start=f.report();auto old=task_personal_message_player_before(f.common,f.family,nullptr,4,start);need(!old.ok&&old.error.original.code=="TaskPersonalMessageControlBoundaryRequired","original Q01 reader rejects the exact legitimate report head");auto fixed=task_personal_report_player_before(f.common,f.family,nullptr,4,start);need(fixed.ok&&fixed.value=="old","new exact report source uses original Family control reader");auto empty_legacy=task_personal_report_player_before(f.common,f.family,&f.legacy,4,start);need(empty_legacy.ok&&empty_legacy.value=="old","selected empty original Legacy chain remains exact");const auto delivery=f.fact(task_personal_message_started_kind,task_personal_message_started_kind,task_personal_message_module);need(!task_personal_report_player_before(f.common,f.family,nullptr,4,delivery).ok,"report boundary cannot replace Q01's callback");need(task_personal_message_player_before(f.common,f.family,nullptr,4,delivery).ok,"Q01 original source remains valid");
 for(const auto& pair:std::vector<std::pair<StableId,StableId>>{{"wrong_domain",task_personal_report_started_kind},{task_personal_report_module,"wrong_kind"}}){auto id=f.fact(pair.second,pair.second,pair.first);need(!task_personal_report_player_before(f.common,f.family,nullptr,4,id).ok,"foreign kind or domain rejects");}auto wrong_prefix=f.fact("other",task_personal_report_started_kind,task_personal_report_module);need(!task_personal_report_player_before(f.common,f.family,nullptr,4,wrong_prefix).ok,"correct header cannot authorize wrong canonical prefix");need(!task_personal_report_player_before(f.common,f.family,nullptr,4,"task_personal_report_started:999").ok,"missing real head rejects");
 DynamicStepInput phase{4,5};need(!task_personal_report_player_before(f.common,f.family,nullptr,5,start,&phase).ok,"zero-time start cannot borrow phase.to");auto finish=f.report(task_personal_report_completed_kind);need(!task_personal_report_player_before(f.common,f.family,nullptr,5,finish).ok,"future finish without strict phase rejects");auto progressed=task_personal_report_player_before(f.common,f.family,nullptr,5,finish,&phase);need(progressed.ok&&progressed.value=="old","actual finish phase.to folds stable from control");auto bad=phase;bad.to_tick=6;need(!task_personal_report_player_before(f.common,f.family,nullptr,5,finish,&bad).ok,"invented future phase rejects");
 Fixture before;before.switch_old();auto later=before.report();auto current=task_personal_report_player_before(before.common,before.family,nullptr,4,later);need(current.ok&&current.value=="new","same-tick earlier actual control uses successor");Fixture after;auto earlier=after.report();auto changed=after.switch_old();auto historical=task_personal_report_player_before(after.common,after.family,nullptr,4,earlier);need(historical.ok&&historical.value=="old","later control does not rewrite prior report actor");auto swapped=after.common.state().facts;after.common.state().facts={};after.common.state().facts.insert(changed,*swapped.find(changed));after.common.state().facts.insert(earlier,*swapped.find(earlier));need(!task_personal_report_player_before(after.common,after.family,nullptr,4,earlier).ok,"same-tick Common order cannot cross global allocation order");
 Fixture legacy;const auto original=legacy.report();legacy.switch_legacy();auto prior=task_personal_report_player_before(legacy.common,legacy.family,&legacy.legacy,4,original);need(prior.ok&&prior.value=="old","later actual Legacy activation preserves old source");auto next=legacy.report(task_personal_report_interrupted_kind);auto newest=task_personal_report_player_before(legacy.common,legacy.family,&legacy.legacy,4,next);need(newest.ok&&newest.value=="new","interruption after actual Legacy uses exact successor");
 std::cout<<checks<<" report control boundary checks; full Family authorization and Task transaction separate\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
